const body = $input.item.json.body || $input.item.json;
if (!body.ticketId || !body.subject || !body.description) {
  throw new Error('Malformed Ticket: ticketId, subject, and description are required.');
}

return {
  json: {
    ticketId: body.ticketId,
    customerEmail: (body.email || 'unknown@customer.com').toLowerCase(),
    tier: body.planTier || 'STANDARD',
    subject: body.subject,
    description: body.description,
    submittedAt: new Date().toISOString()
  }
};
